mapper.select:
SELECT n.chain_code AS chain_code, c.chain_name AS chain_name, n.request_url AS request_url, n.request_method AS request_method, n.interface_scope AS interface_scope, n.target_system AS target_system FROM test_node_config n LEFT JOIN test_chain c ON c.chain_code = n.chain_code WHERE n.request_url IS NOT NULL AND n.request_url != ''
AND n.chain_code = #{chainCode}
ORDER BY n.chain_code ASC, n.node_id ASC
